#include <iostream>
using namespace std;

int main() {
    int a1, a2;
    cin >> a1 >> a2;
    int n = 0;
    while (true) {
        if (a1 < a2) {
            a1 += 1;
            a2 -= 2;
        } else {
            a1 -= 2;
            a2 += 1;
        }
        if (a1 > 0 && a2 > 0) {
            n += 1;
        } else if (a1 == 0 || a2 == 0) {
            n += 1;
            cout << n << endl;
            return 0;
        } else {
            cout << n << endl;
            return 0;
        }
    }
}

